/* CHIP1 — SHARED PER-STRIP KERNELS (DSP4_SHARED_KERNELS) */
/* AUTO-GENERATED by tools/dsp/dsp_codegen.py — do not edit directly. */
/*
 * ONE body per class, entered per strip with that strip's record
 * base in a DAG register. The bodies here are the SAME emitters'
 * output as the inline arm in the node files -- generated from one
 * node and rewritten from absolute per-node addresses to record
 * offsets -- so the two arms cannot drift apart.
 *
 * The record layout is checked against the linker map after the
 * build by tools/dsp/shared_kernel_check.py. Do not assume it.
 */
#include "dsp_block.h"
#include "blk_pool.h"

#if !DSP4_BLOCK_KERNELS && DSP4_SHARED_KERNELS
#error "DSP4_SHARED_KERNELS needs DSP4_BLOCK_KERNELS: the stub stands where a per-block kernel call already was."
#endif

/* ==== COMP: one body for 32 strips ====
 * rewritten sites: 46 direct accesses, 4 DAG base loads, 4 address-to-register,
 * 2 predecessor-buffer accesses. */
#if (DSP4_SHARED_KERNELS & 1)
#define SHK_COMP_OFF_comp_on         (0)
#define SHK_COMP_OFF_comp_threshold  (SHK_COMP_OFF_comp_on + 1)
#define SHK_COMP_OFF_comp_ratio      (SHK_COMP_OFF_comp_threshold + 1)
#define SHK_COMP_OFF_comp_attack     (SHK_COMP_OFF_comp_ratio + 1)
#define SHK_COMP_OFF_comp_release    (SHK_COMP_OFF_comp_attack + 1)
#define SHK_COMP_OFF_comp_makeup     (SHK_COMP_OFF_comp_release + 1)
#define SHK_COMP_OFF_comp_makeup_target (SHK_COMP_OFF_comp_makeup + 1)
#define SHK_COMP_OFF_comp_makeup_step (SHK_COMP_OFF_comp_makeup_target + 1)
#define SHK_COMP_OFF_comp_makeup_frames (SHK_COMP_OFF_comp_makeup_step + 1)
#define SHK_COMP_OFF_comp_knee       (SHK_COMP_OFF_comp_makeup_frames + 1)
#define SHK_COMP_OFF_comp_parallel   (SHK_COMP_OFF_comp_knee + 1)
#define SHK_COMP_OFF_comp_type       (SHK_COMP_OFF_comp_parallel + 1)
#define SHK_COMP_OFF_comp_key_src    (SHK_COMP_OFF_comp_type + 1)
#define SHK_COMP_OFF_comp_det_src    (SHK_COMP_OFF_comp_key_src + 1)
#define SHK_COMP_OFF_comp_eq_pos     (SHK_COMP_OFF_comp_det_src + 1)
#define SHK_COMP_OFF_comp_lim_mode   (SHK_COMP_OFF_comp_eq_pos + 1)
#define SHK_COMP_OFF_comp_filter_on  (SHK_COMP_OFF_comp_lim_mode + 1)
#define SHK_COMP_OFF_comp_filter_coeffs (SHK_COMP_OFF_comp_filter_on + 1)
#define SHK_COMP_OFF_comp_filter_state (SHK_COMP_OFF_comp_filter_coeffs + 10)
#define SHK_COMP_OFF_comp_envelope   (SHK_COMP_OFF_comp_filter_state + 4)
#define SHK_COMP_OFF_comp_gain       (SHK_COMP_OFF_comp_envelope + 1)
#define SHK_COMP_OFF_comp_attq       (SHK_COMP_OFF_comp_gain + 1)
#define SHK_COMP_OFF_comp_relq       (SHK_COMP_OFF_comp_attq + 1)
#define SHK_COMP_OFF_comp_mkq        (SHK_COMP_OFF_comp_relq + 1)
#define SHK_COMP_OFF_comp_parq       (SHK_COMP_OFF_comp_mkq + 1)
#define SHK_COMP_OFF_comp_cgp        (SHK_COMP_OFF_comp_parq + 1)
#if DSP4_DYN_LUT
#define SHK_COMP_OFF_comp_lut        (SHK_COMP_OFF_comp_cgp + 4)
#define SHK_COMP_OFF_comp_lutc       (SHK_COMP_OFF_comp_lut + DYN_LUT_N)
#define SHK_COMP_OFF_comp_lutk       (SHK_COMP_OFF_comp_lutc + 1)
#define SHK_COMP_CUR0 (SHK_COMP_OFF_comp_lutk + 4)
#else
#define SHK_COMP_CUR0 (SHK_COMP_OFF_comp_cgp + 4)
#endif
#define SHK_COMP_OFF_buf             (SHK_COMP_CUR0)
#if DSP4_BLOCK_KERNELS
#define SHK_COMP_OFF_comp_saved_idx  (SHK_COMP_OFF_buf + 1)
#define SHK_COMP_CUR1 (SHK_COMP_OFF_comp_saved_idx + 1)
#else
#define SHK_COMP_CUR1 (SHK_COMP_OFF_buf + 1)
#endif
#define SHK_COMP_REC_LEN             (SHK_COMP_CUR1)

.section/pm seg_pmco;
        .extern _sample_idx;
        .extern _envq_fx;
        .extern _compgain_fx;
        .extern _mrf_rns28;
#if DSP4_DYN_LUT
        .extern _dyn_lut_step;
        .extern _dyn_lut_gain;
#endif
        .global _shk_comp_blk;
        _shk_comp_blk:

        #if DSP4_BLOCK_KERNELS
            /* ---- per-block kernel ----
             * Sample 0 goes through the per-sample body with _sample_idx
             * forced to 0, which runs the block-rate makeup ramp and the
             * whole parameter conversion exactly as a per-sample build
             * would -- and avoids duplicating ninety lines of conversion
             * here. Samples 1..BLOCK-1 then run hoisted.
             *
             * THE LOOP COUNT IS DSP4_BLOCK_SIZE-1 AND IT USED TO BE A
             * LITERAL 31. That literal survived the block-size
             * parameterisation (2026-08-28) because it is the only loop
             * count in the generator that was written as a number rather
             * than derived, and nothing downstream could see it: at
             * BLOCK=8 the compressor ran 1+31 = 32 samples of an 8-sample
             * block, reading 32 words from BLK_CHAIN_A_P1 and writing 32 to
             * BLK_CHAIN_B_P1 -- three slots past the end of each, over
             * BLK_FDR_L_P1/R and BLK_TAP_TRIM_P1. It is what made COMP look
             * BLOCK-INVARIANT (13.5k cycles/block at both block sizes);
             * it was doing the same 32 samples of work either way.
             *
             * The earlier verdict that COMP was not worth converting came
             * from a bare WRAP, which measured 8 % SLOWER, and from a
             * reading that _compgain_fx "clobbers all but four registers".
             * CORRECTED 2026-08-24. An earlier note here claimed r6 also
             * survives, from a scan of _compgain_fx's OWN text. That scan
             * was not transitive: _compgain_fx calls _exp2q_fx, and the
             * polynomial _exp2q_fx reaches r6. Keeping attq in r6 meant
             * the attack alpha was destroyed after the first sample and
             * the envelope follower ran on garbage for the rest of the
             * block -- visible as a compressor output FROZEN from sample 1
             * while a correct build converged smoothly. It never showed in
             * the earlier verification because that ran on a silent bench,
             * where _compgain_fx returns unity before it ever reaches
             * exp2.
             *
             * The survivors across BOTH _envq_fx (r0, r2, r4, r5) and
             * _compgain_fx WITH ITS CALLEES (r0-r6, r8-r12) are r7, r13,
             * r14 and r15 -- which is exactly what the original note on
             * this page said before it was overridden. Four registers, so
             * the release alpha goes back to a DM load per sample. */

            r2 = dm(SHK_COMP_OFF_comp_on, i7);
            r2 = pass r2;
            if eq jump (pc, .ckb_copy_shkcomp);

            r5 = dm(_sample_idx);
            dm(SHK_COMP_OFF_comp_saved_idx, i7) = r5;
            r5 = 0;
            dm(_sample_idx) = r5;
            r0 = dm(i3, 1);
            dm(i5, 0) = r0;
            call _shk_comp_smp;
            r0 = dm(SHK_COMP_OFF_buf, i7);
            dm(i4, 1) = r0;
            r5 = 1;
            dm(_sample_idx) = r5;

            r7 = dm(SHK_COMP_OFF_comp_attq, i7);
            r14 = dm(SHK_COMP_OFF_comp_envelope, i7);
            r15 = dm(SHK_COMP_OFF_comp_mkq, i7);

            lcntr = DSP4_BLOCK_SIZE-1, do .ckb_lp_shkcomp until lce;
                r13 = dm(i3, 1);
                r0 = abs r13;
                r1 = r14;
                r2 = r7;                  /* attq */
                r3 = dm(SHK_COMP_OFF_comp_relq, i7);
                call _envq_fx;
                r14 = r0;
#if DSP4_DYN_LUT
                /* The SCALAR FALLBACK path, so the test is inside the
                 * loop rather than the loop being duplicated: this runs
                 * only when a pair could not be formed, and correctness
                 * there matters more than the branch. */
                r4 = dm(SHK_COMP_OFF_comp_lutc, i7);
                r5 = DYN_LUT_N;
                comp(r4, r5);
                if lt jump (pc, .ckblutp_shkcomp);
                i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_lut);
                call _dyn_lut_gain;
                jump (pc, .ckblutg_shkcomp);
            .ckblutp_shkcomp:
#endif
                i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_cgp);
                call _compgain_fx;
#if DSP4_DYN_LUT
            .ckblutg_shkcomp:
#endif
                dm(SHK_COMP_OFF_comp_gain, i7) = r0;
                r1 = r0;
                r0 = r13;
                mrf = r0 * r1 (ssi);
                call _mrf_rns28;
                r1 = r15;
                mrf = r0 * r1 (ssi);
                call _mrf_rns28;
                r5 = r0 - r13;
                r4 = dm(SHK_COMP_OFF_comp_parq, i7);
                mrf = r5 * r4 (ssi);
                r1 = 0x40000000;
                r12 = 1;
                mrf = mrf + r1 * r12 (ssi);
                r1 = mr0f;
                r12 = mr1f;
                r1 = lshift r1 by -31;
                r12 = lshift r12 by 1;
                r1 = r1 or r12;
                r0 = r13 + r1;
                nop;
                nop;
            .ckb_lp_shkcomp: dm(i4, 1) = r0;

            dm(SHK_COMP_OFF_comp_envelope, i7) = r14;
            r5 = dm(SHK_COMP_OFF_comp_saved_idx, i7);
            dm(_sample_idx) = r5;
            rts;

        .ckb_copy_shkcomp:
            lcntr = DSP4_BLOCK_SIZE, do .ckb_cp_shkcomp until lce;
                r0 = dm(i3, 1);
            .ckb_cp_shkcomp: dm(i4, 1) = r0;
            rts;

        .global _shk_comp_smp;
        _shk_comp_smp:
        #endif

            r0 = dm(i5, 0);
            r2 = dm(SHK_COMP_OFF_comp_on, i7);
            r3 = 0;
            comp(r2, r3);
            if eq jump (pc, .comp_bypass_shkcomp);
            r13 = r0;                     /* dry (r13-r15 lib-safe) */
        #if DSP4_COMP_NOCVT
            jump (pc, .comp_go_shkcomp);   /* TEMP bisect: skip block-rate cvt */
        #endif

            /* --- block rate: makeup ramp + param conversion --- */
        /* Kept in BOTH builds: this node has a block kernel that drives
         * _sample_idx before reaching here, so the guard fires exactly
         * once per block and is doing its job. */
            r4 = dm(_sample_idx);
            r1 = 0;
            comp(r4, r1);
            if ne jump (pc, .comp_go_shkcomp);

            r4 = dm(SHK_COMP_OFF_comp_makeup_frames, i7);
            comp(r4, r1);
            if le jump (pc, .no_mramp_shkcomp);
            /* Consume a BLOCK's worth of frames and apply a BLOCK's
             * worth of step. spi_handler scales every profile frame count
             * by DSP4_BLOCK_SIZE, which is right for the ramps that
             * decrement once per SAMPLE. This one decrements once per
             * BLOCK, so taking 1 per block ran it BLOCK times long:
             * measured 2026-08-23 at BLOCK=32, a GainSafe down-ramp took
             * 960 ms against the 30 ms its own cell table specifies, and a
             * GainFast fader move took 85 ms instead of 3 ms. A power of
             * two is exact in binary, so scaling the step loses nothing. */
            r5 = DSP4_BLOCK_SIZE;
            r4 = r4 - r5;
            dm(SHK_COMP_OFF_comp_makeup_frames, i7) = r4;
            f1 = dm(SHK_COMP_OFF_comp_makeup, i7);
            f2 = dm(SHK_COMP_OFF_comp_makeup_step, i7);
            r5 = DSP4_BLOCK_F32;              /* BLOCK_SIZE as float */
            f5 = r5;
            f2 = f2 * f5;
            f1 = f1 + f2;
            dm(SHK_COMP_OFF_comp_makeup, i7) = f1;
            jump (pc, .comp_cvt_shkcomp);
        .no_mramp_shkcomp:
            f1 = dm(SHK_COMP_OFF_comp_makeup_target, i7);
            dm(SHK_COMP_OFF_comp_makeup, i7) = f1;
        .comp_cvt_shkcomp:
            r2 = 0x4D800000;
            f2 = r2;
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_mkq, i7) = r1;
            /* PARALLEL BLEND IS PERCENT ON THE WIRE (review finding
             * D40). The master documents Chan[1-32]CompPar as 0-100 %
             * (d32-mx-master.csv, table 0=0/127=100); this used to
             * multiply the raw wire value by 2^31 with no /100, so any
             * documented value of 1 % or more pinned the blend fully wet
             * and the control could not take an intermediate setting at
             * all. The masters win: clamp to the documented 0..100 and
             * scale by 2^31/100. */
            f1 = dm(SHK_COMP_OFF_comp_parallel, i7);
            r2 = 0x00000000;              /* 0 %, documented minimum */
            f2 = r2;
            comp(f1, f2);
            if lt f1 = f2;
            r2 = 0x42C80000;              /* 100 %, documented maximum */
            f2 = r2;
            comp(f1, f2);
            if gt f1 = f2;
            r2 = 0x4BA3D70A;              /* 2^31 / 100 */
            f2 = r2;
            f1 = f1 * f2;
            r1 = fix f1;
            /* CLAMP. parallel = 100 % scales to exactly 2^31, which int32 cannot
             * hold: `fix` wraps and stores -1, so in Q0.31 the MAXIMUM
             * parallel setting blended in essentially nothing and the
             * compressor went fully DRY -- the same output as
             * parallel = 0, with a working compressor sitting behind it.
             * Bench 2026-08-23: par 0.999 settled at -16.49 dBFS on a
             * -6.02 dBFS step, par 1.0 returned the input untouched. */
            r3 = 0;
            r2 = 0x7FFFFFFF;
            comp(r1, r3);
            if lt r1 = pass r2;
            dm(SHK_COMP_OFF_comp_parq, i7) = r1;
            r2 = 0x4F000000;              /* 2^31 float */
            f2 = r2;
            f1 = dm(SHK_COMP_OFF_comp_attack, i7);
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_attq, i7) = r1;
            f1 = dm(SHK_COMP_OFF_comp_release, i7);
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_relq, i7) = r1;
            r2 = 0x4AAA152D;            /* dB -> Q6.25 log2 */
            f2 = r2;
            f1 = dm(SHK_COMP_OFF_comp_threshold, i7);
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp, i7) = r1;    /* thr */
            /* slope = 1 - 1/ratio */
            f6 = dm(SHK_COMP_OFF_comp_ratio, i7);
            f7 = recips f6;
            f8 = f6 * f7;
            r10 = 0x40000000;
            f8 = f10 - f8;
            f7 = f7 * f8;
            f8 = f6 * f7;
            f8 = f10 - f8;
            f6 = f7 * f8;
            r2 = 0x3F800000;
            f5 = r2;
            f5 = f5 - f6;                 /* slope float */
            r2 = 0x4F000000;
            f2 = r2;
            f1 = f5 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp + 1, i7) = r1;
            /* knee: halfk = knee_db/2 in Q6.25 log2; k2 = slope*K/(2*knee) Q6.25 */
            f4 = dm(SHK_COMP_OFF_comp_knee, i7);
            r2 = 0x3DCCCCCD;              /* 0.1 dB min for soft path */
            f3 = r2;
            comp(f4, f3);
            if gt jump (pc, .comp_soft_shkcomp);
            r1 = 0;
            dm(SHK_COMP_OFF_comp_cgp + 2, i7) = r1;
            dm(SHK_COMP_OFF_comp_cgp + 3, i7) = r1;
            jump (pc, .comp_kdone_shkcomp);
        .comp_soft_shkcomp:
            r2 = 0x4AAA152D;
            f2 = r2;
            f1 = f4 * f2;
            r2 = 0x3F000000;              /* 0.5 */
            f3 = r2;
            f1 = f1 * f3;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp + 2, i7) = r1;  /* halfk */
            f7 = recips f4;
            f8 = f4 * f7;
            r10 = 0x40000000;
            f8 = f10 - f8;
            f7 = f7 * f8;
            f8 = f4 * f7;
            f8 = f10 - f8;
            f6 = f7 * f8;
            r2 = 0x4040A8C1;             /* K/2 */
            f3 = r2;
            f6 = f6 * f3;                 /* K/(2*knee_db) */
            f6 = f6 * f5;                 /* * slope */
            r2 = 0x4C000000;              /* 2^25 float */
            f2 = r2;
            f1 = f6 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp + 3, i7) = r1;  /* k2 */
        .comp_kdone_shkcomp:
#if DSP4_DYN_LUT
            /* --- block rate: THE DESIGN STEP (S15) ---
             *
             * The four converted words in _comp_cgp_ ARE the curve. If
             * they have moved since the table was designed, the design
             * restarts; either way DYN_LUT_CHUNK points are filled per
             * block until the cursor reaches the end, and until it does
             * the per-sample body below runs the exact polynomial.
             *
             * WHY NOT ALL AT ONCE: one point is a whole _compgain_fx,
             * about 211 instructions, so a 337-point table is ~71,000
             * cycles against a block's 327,680 -- 22 % of a block for
             * ONE node, and chip 1 has 32 of them.
             *
             * WHY NOT A TWO-TABLE BLEND, which is what S14 proposed for
             * a ramping parameter: tools/dsp/dyn_lut_design.py --blend
             * measures it at 1.13 dB for a 10 dB threshold ramp and
             * 20.2 dB for a 57 dB one, against a 0.1 dB bar, because two
             * curves whose KNEES sit at different levels do not
             * interpolate into the curve whose knee is between them.
             * Running the polynomial while the table is stale is exact,
             * costs only what ships today, and needs no second table.
             *
             * r13 holds the live sample and both _dyn_lut_fill and
             * _compgain_fx under it clobber r0-r12 only. */
            r0 = i7;
            r0 = r0 + SHK_COMP_OFF_comp_cgp;
            r1 = i7;
            r1 = r1 + SHK_COMP_OFF_comp_lutk;
            r2 = i7;
            r2 = r2 + SHK_COMP_OFF_comp_lut;
            r3 = i7;
            r3 = r3 + SHK_COMP_OFF_comp_lutc;
            call _dyn_lut_step;
#endif
        .comp_go_shkcomp:

            /* --- envelope (fixed) --- */
            r0 = abs r13;
            r1 = dm(SHK_COMP_OFF_comp_envelope, i7);
            r2 = dm(SHK_COMP_OFF_comp_attq, i7);
            r3 = dm(SHK_COMP_OFF_comp_relq, i7);
            call _envq_fx;
            dm(SHK_COMP_OFF_comp_envelope, i7) = r0;

            /* --- gain computer --- */
#if DSP4_DYN_LUT
            /* ONE TABLE, level -> gain: no log2, no knee, no exp2. The
             * envelope is already in r0. A table that is still being
             * designed falls through to the polynomial, which is the
             * arithmetic the table is designed against, so the changeover
             * is a step of at most the table's own error (0.0950 dB worst
             * case over the documented parameter sweep, 0.004 dB at the
             * shipped defaults) at one block boundary. */
            r4 = dm(SHK_COMP_OFF_comp_lutc, i7);
            r5 = DYN_LUT_N;
            comp(r4, r5);
            if lt jump (pc, .clutpoly_shkcomp);
            i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_lut);
            call _dyn_lut_gain;           /* r0 = gain Q4.28 */
            jump (pc, .clutgain_shkcomp);
        .clutpoly_shkcomp:
#endif
            i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_cgp);
            call _compgain_fx;            /* r0 = gain Q4.28 */
#if DSP4_DYN_LUT
        .clutgain_shkcomp:
#endif
            dm(SHK_COMP_OFF_comp_gain, i7) = r0;

            /* wet = dry * gain * makeup */
            r1 = r0;
            r0 = r13;
            mrf = r0 * r1 (ssi);
            call _mrf_rns28;
            r1 = dm(SHK_COMP_OFF_comp_mkq, i7);
            mrf = r0 * r1 (ssi);
            call _mrf_rns28;

            /* parallel: out = dry + par*(wet - dry) — matches the float
             * node exactly (par==0 -> dry, its default behaviour) */
            r5 = r0 - r13;
            r4 = dm(SHK_COMP_OFF_comp_parq, i7);
            mrf = r5 * r4 (ssi);
            r1 = 0x40000000;
            r12 = 1;
            mrf = mrf + r1 * r12 (ssi);
            r1 = mr0f;
            r12 = mr1f;
            r1 = lshift r1 by -31;
            r12 = lshift r12 by 1;
            r1 = r1 or r12;
            r0 = r13 + r1;
            dm(SHK_COMP_OFF_buf, i7) = r0;
            rts;
        .comp_bypass_shkcomp:
            dm(SHK_COMP_OFF_buf, i7) = r0;
            rts;
        _shk_comp_blk.end:
#endif

/* ==== TUBE: one body for 32 strips ====
 * rewritten sites: 14 direct accesses, 0 DAG base loads, 0 address-to-register,
 * 2 predecessor-buffer accesses. */
#if (DSP4_SHARED_KERNELS & 2)
#define SHK_TUBE_OFF_tube_on         (0)
#define SHK_TUBE_OFF_tube_sat        (SHK_TUBE_OFF_tube_on + 1)
#define SHK_TUBE_OFF_tube_sat_target (SHK_TUBE_OFF_tube_sat + 1)
#define SHK_TUBE_OFF_tube_sat_step   (SHK_TUBE_OFF_tube_sat_target + 1)
#define SHK_TUBE_OFF_tube_sat_frames (SHK_TUBE_OFF_tube_sat_step + 1)
#define SHK_TUBE_OFF_buf             (SHK_TUBE_OFF_tube_sat_frames + 1)
#define SHK_TUBE_REC_LEN             (SHK_TUBE_OFF_buf + 1)

.section/pm seg_pmco;
.extern _mrf_rns28;
.global _shk_tube_blk;
_shk_tube_blk:

#if DSP4_BLOCK_KERNELS
    /* ---- per-block kernel ----
     * The saturation RAMP is per-sample by design (spi_handler
     * scales profile frame counts by 32 for ramps that decrement
     * once per sample), so `sat` -- and therefore sat_q -- changes
     * within the block while a ramp is running. Only the settled
     * case can hoist the conversion, so a ramping TUBE hands the
     * block to the per-sample body. A sat ramp is a transient. */

    r2 = dm(SHK_TUBE_OFF_tube_on, i7);
    r2 = pass r2;
    if eq jump (pc, .tkb_copy_shktube);
    r4 = dm(SHK_TUBE_OFF_tube_sat_frames, i7);
    r5 = 1;
    r4 = r4 - r5;
    if gt jump (pc, .tkb_ref_shktube);     /* ramping */

    f3 = dm(SHK_TUBE_OFF_tube_sat_target, i7);
    dm(SHK_TUBE_OFF_tube_sat, i7) = f3;
    r4 = 0x4D800000;
    f4 = r4;
    f3 = f3 * f4;
    r9 = fix f3;                          /* sat_q, hoisted */

    lcntr = DSP4_BLOCK_SIZE, do .tkb_lp_shktube until lce;
        r8 = dm(i3, 1);
        mrf = r8 * r8 (ssi);
        call _mrf_rns28;
        r10 = 0x10000000;
        r10 = r10 - r0;
        mrf = r9 * r10 (ssi);
        call _mrf_rns28;
        r10 = 0x10000000;
        r10 = r10 + r0;
        mrf = r8 * r10 (ssi);
        call _mrf_rns28;
        nop;
        nop;
    .tkb_lp_shktube: dm(i4, 1) = r0;
    rts;

.tkb_copy_shktube:
    lcntr = DSP4_BLOCK_SIZE, do .tkb_cp_shktube until lce;
        r0 = dm(i3, 1);
    .tkb_cp_shktube: dm(i4, 1) = r0;
    rts;

.tkb_ref_shktube:
    lcntr = DSP4_BLOCK_SIZE, do .tkb_rl_shktube until lce;
        r0 = dm(i3, 1);
        dm(i5, 0) = r0;
        call _shk_tube_smp;
        r0 = dm(SHK_TUBE_OFF_buf, i7);
    .tkb_rl_shktube: dm(i4, 1) = r0;
    rts;

.global _shk_tube_smp;
_shk_tube_smp:
#endif

    r0 = dm(i5, 0);

    r4 = dm(SHK_TUBE_OFF_tube_sat_frames, i7);
    r15 = 1;
    r4 = r4 - r15;
    if le jump (pc, .no_tramp_shktube);
    dm(SHK_TUBE_OFF_tube_sat_frames, i7) = r4;
    f3 = dm(SHK_TUBE_OFF_tube_sat, i7);
    f2 = dm(SHK_TUBE_OFF_tube_sat_step, i7);
    f3 = f3 + f2;
    dm(SHK_TUBE_OFF_tube_sat, i7) = f3;
    jump (pc, .tube_go_shktube);
.no_tramp_shktube:
    f3 = dm(SHK_TUBE_OFF_tube_sat_target, i7);
    dm(SHK_TUBE_OFF_tube_sat, i7) = f3;
.tube_go_shktube:

    r2 = dm(SHK_TUBE_OFF_tube_on, i7);
    r2 = pass r2;
    if eq jump (pc, .tube_bypass_shktube);

    r8 = r0;                      /* x */
    r4 = 0x4D800000;              /* sat -> Q4.28 */
    f4 = r4;
    f3 = f3 * f4;
    r9 = fix f3;                  /* sat_q */

    mrf = r8 * r8 (ssi);
    call _mrf_rns28;              /* r0 = x^2 */
    r10 = 0x10000000;             /* 1.0 Q4.28 */
    r10 = r10 - r0;               /* 1 - x^2 */
    mrf = r9 * r10 (ssi);
    call _mrf_rns28;              /* sat*(1-x^2) */
    r10 = 0x10000000;
    r10 = r10 + r0;               /* 1 + sat*(1-x^2) */
    mrf = r8 * r10 (ssi);
    call _mrf_rns28;              /* y */
    jump (pc, .tube_out_shktube);
.tube_bypass_shktube:
    nop;
.tube_out_shktube:
    dm(SHK_TUBE_OFF_buf, i7) = r0;
    rts;
_shk_tube_blk.end:
#endif
